ll n; cin >> n;
vector<ll> a(n); for (auto &x : a) { cin >> x; x = llabs(x); }
ll mn = *min_element(a.begin(), a.end()), best = 0;
auto all_div = [&](ll d) { for (ll x : a) if (x % d) return false; return true; };
for (ll d = 1; d * d <= mn; d++) if (mn % d == 0) {   // brute: każdy dzielnik min sprawdzany na całej tablicy
    if (all_div(d)) best = max(best, d);
    if (all_div(mn / d)) best = max(best, mn / d);
}
if (mn == 0) { ll g = 0; for (ll x : a) g = __gcd(g, x); best = g; }
cout << best << "\n";

